import java.util.*;

class Solution {
  public int[] findRightInterval(int[][] intervals) {
    TreeMap<Integer, Integer> starts = new TreeMap<>(); // start -> index (starts are unique)
    for (int i = 0; i < intervals.length; i++) starts.put(intervals[i][0], i);
    int[] ans = new int[intervals.length];
    for (int i = 0; i < intervals.length; i++) {
      Map.Entry<Integer, Integer> e = starts.ceilingEntry(intervals[i][1]);
      ans[i] = e == null ? -1 : e.getValue();
    }
    return ans;
  }
}
